font=FontBuilder(800,isTTF=True);font.setupGlyphOrder(order);font.setupCharacterMap({ord(c):f'u{ord(c):04X}' for c in patterns})
glyphs={};metrics={}
for name,pattern in [('.notdef','11111/10001/10101/10101/10101/10001/11111')]+[(f'u{ord(c):04X}',p) for c,p in patterns.items()]:
 pen=TTGlyphPen(None)
 for y,row in enumerate(pattern.split('/')):
  for x,value in enumerate(row):
   if value=='1':
    left=x*100;bottom=(6-y)*100;pen.moveTo((left,bottom));pen.lineTo((left,bottom+100));pen.lineTo((left+100,bottom+100));pen.lineTo((left+100,bottom));pen.closePath()
